style.css:
/* 1. Перекрашиваем абсолютно всё: фон, границы и текст */
* {
    background-color: #121212 !important; /* Глубокий темный фон */
    color: #e0e0e0 !important;            /* Светло-серый текст */
    border-color: #333333 !important;      /* Темные границы (чтобы не было белых рамок) */
}

/* 2. Настройка ссылок (как вы просили) */
a {
    color: #d3d3d3 !important;            /* Светло-серые ссылки */
    text-decoration: underline !important;
}

a:hover {
    color: #0077be !important;            /* Темно-голубые при наведении */
}

/* 3. Исключения для медиа (чтобы картинки не пропадали) */
img, video, canvas, svg {
    background-color: transparent !important; /* Не закрашивать фон у картинок */
    filter: brightness(0.8);                 /* Чуть приглушаем яркость картинок, чтобы не слепили */
}

/* 4. Поля ввода (чтобы видеть, что печатаешь) */
input, textarea, select {
    background-color: #1e1e1e !important;
    border: 1px solid #444 !important;
    color: #ffffff !important;
}
